import heapq

def match(orders):
    buy_heap = []
    sell_heap = []
    book = {}  # id -> dict with side, price, qty, seq, active
    trades = []
    seq = 0

    def add_to_book(oid):
        info = book[oid]
        if info['side'] == 'buy':
            heapq.heappush(buy_heap, (-info['price'], info['seq'], oid))
        else:
            heapq.heappush(sell_heap, (info['price'], info['seq'], oid))

    def top_valid(heap):
        while heap:
            item = heap[0]
            oid = item[2]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(heap)
                continue
            return oid
        return None

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in book and book[oid]['active'] and book[oid]['qty'] > 0:
                book[oid]['active'] = False
            continue

        oid = order[1]
        side = order[2]
        if typ == 'market':
            price = None
            qty = order[3]
        else:
            price = order[3]
            qty = order[4]

        seq += 1
        remaining = qty

        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0:
            opp_id = top_valid(opp_heap)
            if opp_id is None:
                break
            opp_info = book[opp_id]
            if typ != 'market':
                if side == 'buy' and opp_info['price'] > price:
                    break
                if side == 'sell' and opp_info['price'] < price:
                    break
            trade_qty = min(remaining, opp_info['qty'])
            trade_price = opp_info['price']
            if side == 'buy':
                trades.append([oid, opp_id, trade_price, trade_qty])
            else:
                trades.append([opp_id, oid, trade_price, trade_qty])
            remaining -= trade_qty
            opp_info['qty'] -= trade_qty
            if opp_info['qty'] == 0:
                opp_info['active'] = False
                heapq.heappop(opp_heap)

        if typ == 'limit' and remaining > 0:
            book[oid] = {'side': side, 'price': price, 'qty': remaining, 'seq': seq, 'active': True}
            add_to_book(oid)
        # ioc/market remainders are discarded

    return trades

